const key='burnfit-data-v1', days=['周一','周二','周三','周四','周五','周六','周日'];
const defaults=[{day:'周一',title:'下肢力量 A',exercises:[['杠铃深蹲',4,'8'],['罗马尼亚硬拉',3,'10'],['保加利亚分腿蹲',3,'10'],['平板支撑',3,'45 秒']]},{day:'周三',title:'上肢力量 A',exercises:[['卧推',4,'8'],['哑铃划船',3,'10']]},{day:'周五',title:'全身力量 B',exercises:[['硬拉',3,'5'],['肩推',3,'10']]}].map(p=>({...p,exercises:p.exercises.map(([name,sets,reps])=>({name,sets,reps}))}));
const initial={workoutDone:false,workouts:0,streak:0,completedDates:[],calories:0,protein:0,carbs:0,fat:0,meals:[],weights:[68.9,68.8,68.8,68.7,68.6,68.5,68.4],plans:defaults,settings:{font:'system',theme:'blue',language:'zh-Hant'}};
let state=JSON.parse(localStorage.getItem(key)||'null')||structuredClone(initial);if(!state.plans)state.plans=structuredClone(defaults);if(!state.settings)state.settings={font:'system',theme:'blue',language:'zh-Hant'};if(!state.settings.language)state.settings.language='zh-Hant';if(!Array.isArray(state.completedDates)){state.completedDates=[];state.streak=0;state.workouts=0;state.workoutDone=false}let selectedDay='周一',draft=[];const $=s=>document.querySelector(s),save=()=>localStorage.setItem(key,JSON.stringify(state)),plan=()=>state.plans.find(p=>p.day===selectedDay);
NutritionDates.rollover(state);
function renderDraft(){ $('#draftExerciseList').innerHTML=draft.length?draft.map((x,i)=>`<li><span><b>${x.name}</b> · ${x.sets} 組 × ${x.reps}</span><button type="button" data-remove="${i}">移除</button></li>`).join(''):'<li class="muted">先從上方選擇動作加入計劃。</li>';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{draft.splice(+b.dataset.remove,1);renderDraft()})}
function load(day){selectedDay=day;const p=plan();$('#planDay').value=day;$('#planTitle').value=p?.title||'';draft=structuredClone(p?.exercises||[]);$('#logTitle').textContent=p?.title||'今天的訓練';renderDraft();render()}
function render(){const p=plan(),today=p||state.plans[0];$('#streakValue').textContent=state.streak;$('#workoutProgress').textContent=state.workoutDone?'1 / 1':'0 / 1';$('#workoutStatus').textContent=state.workoutDone?'已完成':'待開始';$('#workoutStatus').classList.toggle('done',state.workoutDone);$('#completeWorkout').textContent=state.workoutDone?'今日訓練已完成':'完成训练';$('#completeWorkout').disabled=state.workoutDone;$('#todayWorkoutTitle').textContent=today?.title||'今天自由安排';$('#todayWorkoutMeta').textContent=today?`自訂計劃 · ${today.exercises.length} 個動作`:'還沒有安排訓練';$('#todayExerciseList').innerHTML=today?today.exercises.map(x=>`<li>${x.name}<span>${x.sets} × ${x.reps}</span></li>`).join(''):'<li>前往「訓練」建立你的計劃</li>';$('#calorieRemaining').textContent=Math.round(Math.max(0,2100-state.calories)).toLocaleString('zh-CN');$('#proteinValue').textContent=state.protein;$('#ringCalories').textContent=state.calories;$('#macroProtein').textContent=`${state.protein} / 120 g`;$('#macroCarbs').textContent=`${state.carbs} / 230 g`;$('#macroFat').textContent=`${state.fat} / 65 g`;$('#mealCount').textContent=`${state.meals.length} 餐`;$('#mealList').innerHTML=state.meals.map(m=>`<li><span>${m.name}<small>蛋白質 ${m.protein} g</small></span><b>${m.calories} kcal</b></li>`).join('');$('#weeklyWorkouts').textContent=state.workouts;const w=state.weights.at(-1);$('#latestWeight').textContent=`${w.toFixed(1)} kg`;$('#weightInput').value=w.toFixed(1);const lo=Math.min(...state.weights)-.15,hi=Math.max(...state.weights)+.15;$('#weightChart').innerHTML=state.weights.map((w,i)=>`<span class="bar ${i===6?'current':''}" style="height:${35+(w-lo)/(hi-lo)*55}%"></span>`).join('');$('#weekList').innerHTML=days.map(day=>{const p=state.plans.find(x=>x.day===day);return `<div class="week-item ${day===selectedDay?'selected':''}" data-day="${day}"><span class="day">${day}</span><span class="activity">${p?p.title:'休息 / 未安排'}</span><span>${p?'編輯':'＋'}</span></div>`}).join('');document.querySelectorAll('[data-day]').forEach(x=>x.onclick=()=>load(x.dataset.day));$('#coachTitle').textContent=state.workoutDone?'訓練完成，安排一餐恢復':'先完成訓練，再補一餐蛋白質';$('#coachAdvice').textContent=state.workoutDone?'今天的計劃已完成。接下來補足蛋白質並好好休息。':'計劃完全由你決定；完成後，記得以蛋白質與睡眠協助恢復。';save()}
function dateKey(offset=0){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10)}function calculateStreak(){let count=0,offset=0;while(state.completedDates.includes(dateKey(offset))){count++;offset--}return count}function complete(){if(!state.workoutDone){const today=dateKey();state.workoutDone=true;if(!state.completedDates.includes(today))state.completedDates.push(today);state.workouts=state.completedDates.length;state.streak=calculateStreak();render()}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.view,.nav-link').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');b.classList.add('active')});document.querySelectorAll('[data-view-target]').forEach(b=>b.onclick=()=>document.querySelector(`[data-view="${b.dataset.viewTarget}"]`).click());$('#completeWorkout').onclick=complete;$('#workoutQuickComplete').onclick=complete;
$('#exercisePreset').onchange=()=>$('#customExerciseWrap').hidden=$('#exercisePreset').value!=='custom';$('#addExercise').onclick=()=>{const name=($('#exercisePreset').value==='custom'?$('#customExercise').value:$('#exercisePreset').value).trim(),sets=+$('#exerciseSets').value,reps=$('#exerciseReps').value.trim();if(!name||!sets||!reps){$('#planSaved').textContent='請先完整填寫動作、組數與次數。';return}draft.push({name,sets,reps});$('#customExercise').value='';$('#planSaved').textContent='';renderDraft()};$('#planDay').onchange=e=>load(e.target.value);$('#planForm').onsubmit=e=>{e.preventDefault();const title=$('#planTitle').value.trim();if(!title||!draft.length){$('#planSaved').textContent='請填寫名稱，並至少加入一個動作。';return}state.plans=state.plans.filter(p=>p.day!==selectedDay);state.plans.push({day:selectedDay,title,exercises:structuredClone(draft)});$('#planSaved').textContent=`已儲存 ${selectedDay} 的「${title}」。`;render()};
$('#workoutForm').onsubmit=e=>{e.preventDefault();$('#workoutSaved').textContent=`已保存：RPE ${$('#rpe').value}，${$('#workoutResult').value}。`};$('#mealForm').onsubmit=e=>{e.preventDefault();const m={name:$('#mealName').value.trim(),calories:+$('#mealCalories').value,protein:+$('#mealProtein').value};state.meals.push(m);state.calories+=m.calories;state.protein+=m.protein;state.carbs+=Math.round(m.calories*.11);state.fat+=Math.round(m.calories*.025);e.target.reset();$('#mealSaved').textContent='已加入今日飲食記錄。';render()};$('#addWeightButton').onclick=()=>$('#weightDialog').showModal();$('#weightForm').onsubmit=e=>{e.preventDefault();const w=+$('#weightInput').value;if(w){state.weights=[...state.weights.slice(-6),w];$('#weightDialog').close();render()}};$('#resetData').onclick=()=>{if(confirm('恢復示範資料？你目前的本地記錄將被覆蓋。')){state=structuredClone(initial);load('周一')}};
const copy={"zh-Hant":{today:'今日',workout:'訓練',nutrition:'飲食',progress:'進展',settings:'設定',personalization:'個人化',settingsHint:'調整語言、字體與主題色，立刻預覽你的選擇。',language:'語言',font:'字體',theme:'頁面主題色',saved:'設定已套用並儲存在此裝置。'},en:{today:'Today',workout:'Workout',nutrition:'Nutrition',progress:'Progress',settings:'Settings',personalization:'Personalization',settingsHint:'Choose your language, typeface, and accent color.',language:'Language',font:'Typeface',theme:'Accent color',saved:'Your settings are saved on this device.'},ja:{today:'今日',workout:'トレーニング',nutrition:'食事',progress:'進捗',settings:'設定',personalization:'パーソナライズ',settingsHint:'言語、書体、テーマカラーを選択できます。',language:'言語',font:'書体',theme:'テーマカラー',saved:'設定をこのデバイスに保存しました。'}};
function applyLanguage(){const lang=state.settings.language,words=copy[lang];document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=words[node.dataset.i18n]||node.textContent);document.querySelectorAll('[data-language]').forEach(b=>b.classList.toggle('selected',b.dataset.language===lang))}
function applySettings(){document.documentElement.dataset.font=state.settings.font;document.documentElement.dataset.theme=state.settings.theme;document.querySelectorAll('[data-font]').forEach(b=>b.classList.toggle('selected',b.dataset.font===state.settings.font));document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===state.settings.theme));applyLanguage();save()}
document.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>{state.settings.font=b.dataset.font;applySettings();$('#settingsSaved').textContent=copy[state.settings.language].saved});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{state.settings.theme=b.dataset.theme;applySettings();$('#settingsSaved').textContent=copy[state.settings.language].saved});document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>{state.settings.language=b.dataset.language;applySettings();location.reload()});const now=new Date();$('#todayDate').textContent=`${['周日',...days][now.getDay()]} · ${now.getMonth()+1}月${now.getDate()}日`;applySettings();load(selectedDay);
